    return { addColorStop(o, c) { if (!(o >= 0 && o <= 1)) throw new Error('bad stop ' + o); if (typeof c !== 'string') throw new Error('bad color'); } };
  };
  const ctx2d = new Proxy({}, {
    get(t, p) {
      if (p in t) return t[p];
      if (p === 'createLinearGradient' || p === 'createRadialGradient') return (...a) => gradient(p, a);
      if (p === 'measureText') return (s) => ({ width: String(s).length * 10 });
      return (...a) => {
        nums(String(p), a);
        if ((p === 'arc' && a[2] < 0) || (p === 'arcTo' && a[4] < 0)) throw new Error(p + ' negative radius');
        calls[p] = (calls[p] || 0) + 1;
      };
    },
    set(t, p, v) {
      if (typeof v === 'number' && !Number.isFinite(v)) warnings.push('set ' + String(p) + '=' + v);
      if (p === 'font' && !/^\d{3} \d+px "Segoe UI"/.test(v)) warnings.push('odd font: ' + v);
      if (p === 'globalAlpha' && !(v >= 0 && v <= 1)) warnings.push('alpha ' + v);
      t[p] = v; return true;
