// Temporary headless test harness for ../index.html (run with --cleanup to delete this folder).
// Stubs the DOM/canvas/audio, drives keyboard + mouse input and plays both levels with a bot.
const fs = require('fs');
const path = require('path');
const vm = require('vm');

if (process.argv.includes('--cleanup')) {
  fs.rmSync(__dirname, { recursive: true, force: true });
  console.log('removed', __dirname);
  process.exit(0);
}

const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
const code = html.match(/<script>([\s\S]*?)<\/script>/)[1];

function makeEnv(opts) {
  const warnings = [], calls = {}, listeners = {}, store = new Map();
  let raf = null, audioStarts = 0;
  const nums = (name, args) => { for (const a of args) if (typeof a === 'number' && !Number.isFinite(a)) { warnings.push(name + '(' + args.join(',') + ')'); break; } };
  const gradient = (kind, args) => {
    nums(kind, args);
    if (kind === 'createRadialGradient' && (args[2] < 0 || args[5] < 0)) throw new Error('negative radial radius');
    return { addColorStop(o, c) { if (!(o >= 0 && o <= 1)) throw new Error('bad stop ' + o); if (typeof c !== 'string') throw new Error('bad color'); } };
  };
  const ctx2d = new Proxy({}, {
    get(t, p) {
      if (p in t) return t[p];
      if (p === 'createLinearGradient' || p === 'createRadialGradient') return (...a) => gradient(p, a);
      if (p === 'measureText') return (s) => ({ width: String(s).length * 10 });
      return (...a) => {
        nums(String(p), a);
        if ((p === 'arc' && a[2] < 0) || (p === 'arcTo' && a[4] < 0)) throw new Error(p + ' negative radius');
        calls[p] = (calls[p] || 0) + 1;
      };
    },
    set(t, p, v) {
      if (typeof v === 'number' && !Number.isFinite(v)) warnings.push('set ' + String(p) + '=' + v);
      if (p === 'font' && !/^\d{3} \d+px "Segoe UI"/.test(v)) warnings.push('odd font: ' + v);
      if (p === 'globalAlpha' && !(v >= 0 && v <= 1)) warnings.push('alpha ' + v);
      t[p] = v; return true;
    },
  });
  const canvasEl = {
    width: 800, height: 600, style: {},
    getContext: () => ctx2d,
    getBoundingClientRect() { return { left: 100, top: 40, width: parseFloat(this.style.width), height: parseFloat(this.style.height) }; },
  };
  const on = (scope) => (type, fn) => { (listeners[scope + type] = listeners[scope + type] || []).push(fn); };
  const fire = (type, props, scope) => {
    const ev = Object.assign({ type, code: '', key: '', repeat: false, ctrlKey: false, metaKey: false, altKey: false,
      defaultPrevented: false, preventDefault() { this.defaultPrevented = true; } }, props || {});
    for (const fn of listeners[(scope || 'w:') + type] || []) fn(ev);
    return ev;
  };
  class Param {
    setValueAtTime(v, t) { if (!Number.isFinite(v) || !Number.isFinite(t)) throw new Error('bad setValueAtTime'); }
    exponentialRampToValueAtTime(v, t) { if (!Number.isFinite(v) || v === 0 || !Number.isFinite(t)) throw new RangeError('bad ramp'); }
  }
  class FakeNode {
    constructor() { this.frequency = new Param(); this.gain = new Param(); }
    connect(n) { return n; }
    start(t) { if (!Number.isFinite(t)) throw new Error('bad start'); audioStarts++; }
    stop(t) { if (!Number.isFinite(t)) throw new Error('bad stop'); }
  }
  class FakeAudio {
    constructor() { this.state = 'running'; this.currentTime = 0; this.destination = {}; }
    createOscillator() { return new FakeNode(); }
    createGain() { return new FakeNode(); }
    resume() { return Promise.resolve(); }
  }
  const sandbox = {
    console, devicePixelRatio: 1.5, innerWidth: 1280, innerHeight: 720,
    addEventListener: on('w:'),
    requestAnimationFrame(cb) { raf = cb; return 1; },
    document: { getElementById: (id) => (id === 'game' ? canvasEl : null), addEventListener: on('d:'), hidden: false },
    __fire: fire, __raf: () => raf, __store: store, __audio: () => audioStarts,
  };
  if (opts.brokenStorage) Object.defineProperty(sandbox, 'localStorage', { get() { throw new Error('SecurityError'); } });
  else sandbox.localStorage = { getItem: (k) => (store.has(k) ? store.get(k) : null), setItem: (k, v) => { store.set(k, String(v)); } };
  if (!opts.noAudio) sandbox.AudioContext = FakeAudio;
  sandbox.window = sandbox;
  vm.createContext(sandbox);
  vm.runInContext(code, sandbox, { filename: 'index.html<script>' });
  return { sandbox, warnings, calls };
}

// Runs inside the game's context (stringified), so it sees the game's globals.
function tests() {
  const out = [];
  let fails = 0;
  const check = (cond, msg) => { out.push((cond ? '  ok   ' : '  FAIL ') + msg); if (!cond) fails++; };
  const kd = (code, key, extra) => __fire('keydown', Object.assign({ code, key }, extra));
  const ku = (code, key) => __fire('keyup', { code, key });
  const press = (code, key) => { kd(code, key); ku(code, key); };
  const ptr = (type, gx, extra) => {
    const r = canvas.getBoundingClientRect();
    return __fire(type, Object.assign({ clientX: r.left + gx * r.width / W, clientY: r.top + 20, pointerType: 'mouse', button: 0 }, extra));
  };
  const step = (n, dt) => { for (let i = 0; i < n; i++) update(dt || 1 / 60); };
  const draw = (label) => { try { render(); } catch (e) { check(false, 'render threw in ' + label + ': ' + e.stack); } };
  const zero = () => ({ oob: 0, nan: 0, inside: 0, drift: 0, flat: 0 });
  const isZero = (s) => Object.values(s).every((v) => v === 0);
  const hpLeft = () => bricks.reduce((s, b) => s + b.hp, 0);

  function bot(maxFrames, stats) {
    let offset = 0, falling = false, frames = 0;
