      if (ball.vy > 0 && !falling) offset = (Math.random() - 0.5) * paddle.w * 0.9;
      falling = ball.vy > 0;
      paddle.x = clamp(ball.x - offset, paddle.w / 2, W - paddle.w / 2);
      update(1 / 60);
      frames++;
      if (state === 'play') {
        if (!(ball.x >= ball.r - 1e-6 && ball.x <= W - ball.r + 1e-6 && ball.y >= HUD_H + ball.r - 1e-6)) stats.oob++;
        if (!Number.isFinite(ball.x + ball.y + ball.vx + ball.vy)) stats.nan++;
        for (const b of bricks) if (ball.x > b.x && ball.x < b.x + b.w && ball.y > b.y && ball.y < b.y + b.h) stats.inside++;
        if (Math.abs(Math.hypot(ball.vx, ball.vy) - ball.speed) > 1e-6) stats.drift++;
        if (Math.abs(ball.vy) < ball.speed * 0.45) stats.flat++;
      }
      if (frames % 397 === 0) draw('bot frame ' + frames);
    }
    return frames;
  }
  function avoid(maxFrames) {
    let frames = 0;
    while (frames < maxFrames && state === 'play') {
      paddle.x = ball.x < W / 2 ? W - paddle.w / 2 : paddle.w / 2;
      update(1 / 60);
      frames++;
    }
  }

  try {
    check(state === 'menu', 'boots into the menu');
    check(bricks.length === 60, 'level 1 has 60 bricks (' + bricks.length + ')');
    check(lives === 3 && score === 0, 'starts with 3 lives and 0 points');
    check(canvas.width === Math.round(parseFloat(canvas.style.width) * 1.5) && viewSX === canvas.width / 800,
      'canvas fitted to window at DPR 1.5 (' + canvas.style.width + ' css, ' + canvas.width + ' px)');
    step(120); draw('menu');
    __raf()(1000); __raf()(1016); __raf()(9000);
    check(true, 'requestAnimationFrame loop runs (incl. a long frame gap)');
    ptr('pointermove', 100);
    check(paddle.x === W / 2, 'mouse does not move the paddle on the menu');

    press('Space', ' ');
    check(state === 'serve' && levelIndex === 0 && lives === 3 && score === 0, 'Space starts a new game');
    kd('Space', ' ', { repeat: true });
    check(state === 'serve', 'auto-repeated Space does not launch');
    let x0 = paddle.x;
    kd('ArrowLeft', 'ArrowLeft'); step(20); ku('ArrowLeft', 'ArrowLeft');
    check(Math.abs((x0 - paddle.x) - 760 / 3) < 1e-6, 'ArrowLeft steers left at 760 px/s (' + x0 + ' -> ' + paddle.x.toFixed(2) + ')');
    check(ball.x === paddle.x && ball.vx === 0 && ball.vy === 0, 'ball rides the paddle before launch');
    x0 = paddle.x; kd('KeyD', 'd'); step(10); ku('KeyD', 'd');
    check(paddle.x > x0 + 100, 'D steers right');
    x0 = paddle.x; step(10);
    check(paddle.x === x0, 'paddle stops when the key is released');
    kd('KeyA', 'a'); step(200); ku('KeyA', 'a');
    check(paddle.x === paddle.w / 2, 'keyboard steering stops at the left wall');
    const ev = kd('ArrowRight', 'ArrowRight'); ku('ArrowRight', 'ArrowRight');
    check(ev.defaultPrevented, 'arrow keys do not scroll the page');
