    const s1 = zero();
    const f1 = bot(60 * 60 * 20, s1);
    check(state === 'levelClear', 'bot clears level 1 in ' + (f1 / 60).toFixed(0) + 's game time (state=' + state + ', bricks left=' + bricks.length + ')');
    check(__audio() > a0, 'sound effects play (' + (__audio() - a0) + ' tones)');
    check(lives === 3, 'perfect bot lost no lives');
    check(score === 600, 'level 1 score = 60 hits x 10 = 600 (' + score + ')');
    check(isZero(s1), 'level 1 physics invariants ' + JSON.stringify(s1));
    draw('levelClear');
    press('Space', ' ');
    check(state === 'levelClear', 'level-clear screen ignores an instant key press');
    step(40);
    press('Space', ' ');
    check(state === 'serve' && levelIndex === 1, 'Space advances to level 2');
    check(bricks.length === 46 && hpLeft() === 77, 'level 2: 46 bricks needing 77 hits (' + bricks.length + ', ' + hpLeft() + ')');
    check(paddle.w === 104 && ball.speed === 400, 'level 2 is harder (paddle 104, ball 400 px/s)');
    check(lives === 3 && score === 600 && serveTitle === 'LEVEL 2', 'score/lives carry over, level 2 banner shown');
    step(90); draw('serve level 2');
    const s2 = zero();
    const f2 = bot(60 * 60 * 30, s2);
    check(state === 'victory', 'bot clears level 2 in ' + (f2 / 60).toFixed(0) + 's game time (state=' + state + ', bricks left=' + bricks.length + ')');
    check(score === 600 + 77 * 20, 'final score = 600 + 77 x 20 = 2140 (' + score + ')');
    check(isZero(s2), 'level 2 physics invariants ' + JSON.stringify(s2));
    check(best === 2140 && __store.get('brickBreaker.bestScore') === '2140', 'best score saved to localStorage');
    press('Space', ' ');
    check(state === 'victory', 'victory screen ignores an instant key press');
    step(90);
    const n0 = particles.length; firework();
    check(particles.length === n0 + 28, 'victory fireworks spawn');
    draw('victory');
    press('Space', ' ');
    check(state === 'serve' && score === 0 && lives === 3 && levelIndex === 0 && bricks.length === 60, 'Space starts a fresh game from the victory screen');

    press('Space', ' ');
    avoid(3600);
    check(state === 'serve' && lives === 2 && serveTitle === '2 LIVES LEFT', 'missed ball costs a life (lives=' + lives + ', "' + serveTitle + '")');
    check(ball.speed === 340 && ball.vy === 0, 'ball back on the paddle at base speed');
    draw('serve after miss');
    press('ArrowUp', 'ArrowUp');
    check(state === 'play', 'ArrowUp launches');
    avoid(3600);
    check(lives === 1 && serveTitle === 'LAST LIFE!', 'second miss -> last life');
    press('Enter', 'Enter');
    check(state === 'play', 'Enter launches');
    avoid(3600);
    check(state === 'gameOver' && lives === 0, 'third miss -> game over');
    draw('gameOver');
    ptr('pointerdown', 300);
    check(state === 'gameOver', 'game-over screen ignores an instant click');
    step(70);
    ptr('pointerdown', 300);
    check(state === 'serve' && lives === 3 && score === 0, 'click restarts after game over');

    innerWidth = 500; __fire('resize', {});
    check(parseFloat(canvas.style.width) < 480 && canvas.width === Math.round(parseFloat(canvas.style.width) * 1.5), 'resize refits the canvas (' + canvas.style.width + ')');
    ptr('pointermove', 250);
    check(Math.abs(paddle.x - 250) < 1e-6, 'mouse mapping still exact after resize (' + paddle.x + ')');
    draw('after resize');
    innerWidth = 1280; __fire('resize', {});

    let inside = 0, oob = 0, nan = 0, hits = 0;
    for (let trial = 0; trial < 4000; trial++) {
      const li = trial % 2;
      levelIndex = li; buildLevel(li); levelTime = 10; lives = 99; setState('play');
      ball.x = 7 + Math.random() * (W - 14);
      ball.y = 330 + Math.random() * 150;
      ball.speed = 300 + Math.random() * 700;
      const ang = (Math.random() - 0.5) * 2 * MAX_BOUNCE;
      ball.vx = ball.speed * Math.sin(ang);
      ball.vy = -ball.speed * Math.cos(ang);
      const h0 = hpLeft();
      for (let f = 0; f < 45 && state === 'play'; f++) {
        paddle.x = clamp(ball.x, paddle.w / 2, W - paddle.w / 2);
        updateBall(1 / 30);
        if (!Number.isFinite(ball.x + ball.y)) nan++;
        if (ball.x < ball.r - 1e-6 || ball.x > W - ball.r + 1e-6 || ball.y < HUD_H + ball.r - 1e-6) oob++;
        for (const b of bricks) if (ball.x > b.x && ball.x < b.x + b.w && ball.y > b.y && ball.y < b.y + b.h) inside++;
      }
      hits += h0 - hpLeft();
    }
    check(inside === 0 && oob === 0 && nan === 0 && hits > 1000,
      'stress: 4000 fast balls at 30fps steps, no tunnelling/escapes (inside=' + inside + ', oob=' + oob + ', nan=' + nan + ', hits=' + hits + ')');
  } catch (e) {
    fails++;
    out.push('  EXCEPTION ' + e.stack);
  }
  return { out, fails };
}

// Smoke test for hostile environments: storage that throws (sandboxed iframe) and no Web Audio at all.
function smoke() {
  __fire('keydown', { code: 'Space', key: ' ' });
  __fire('pointerdown', { clientX: 500, clientY: 300, pointerType: 'mouse', button: 0 });
  for (let i = 0; i < 3000; i++) {
    paddle.x = clamp(ball.x, paddle.w / 2, W - paddle.w / 2);
    if (state === 'serve') onAction();
    update(1 / 60);
    if (i % 50 === 0) render();
  }
  if (score <= 0) throw new Error('no score in smoke run');
}

